  await Assert("PrismWorkspace.state.section==='dock'&&document.querySelector('#settings-search').hidden&&document.querySelector('[data-setting=windowAnimations]')&&document.activeElement.id==='settings-title'","selecting a result opens the real Dock settings with an accessible focus target");
  await Eval("document.querySelector('[data-page=welcome]').click();querySettings('窗口动画');document.querySelector('#settings-query').dispatchEvent(new CompositionEvent('compositionstart',{bubbles:true}));document.querySelector('#settings-search').requestSubmit()");await Assert("PrismWorkspace.state.section==='welcome'","confirming Chinese composition cannot open a settings page");
  await Eval("document.querySelector('#settings-query').dispatchEvent(new CompositionEvent('compositionend',{bubbles:true}));document.querySelector('#settings-search').requestSubmit()");await Assert("PrismWorkspace.state.section==='dock'","Enter submits the first result after composition finishes");
  await Eval("document.querySelector('[data-page=welcome]').click();querySettings('这项不存在<img>')");await Assert("document.querySelector('#settings-search-results').hidden&&document.querySelector('#settings-search-status').textContent.includes('没有找到')&&!document.querySelector('#settings-search img')","unknown text has a clear empty state and is never interpreted as markup");
