 [STAThread]static void Main(string[] args){SetProcessDPIAware();welcomeOnly=Array.IndexOf(args,"--welcome-only")>=0;if(welcomeOnly)logName="welcome-checks.txt";settingsSearchOnly=Array.IndexOf(args,"--settings-search-only")>=0;if(settingsSearchOnly)logName="settings-search-checks.txt";editorSyncOnly=Array.IndexOf(args,"--editor-sync-only")>=0;materialOnly=Array.IndexOf(args,"--materials-only")>=0;photoOnly=Array.IndexOf(args,"--photos-only")>=0||Environment.GetEnvironmentVariable("PRISM_TEST_PHOTOS")=="1";glassOnly=Array.IndexOf(args,"--glass-only")>=0;controlCenterOnly=Array.IndexOf(args,"--control-center-only")>=0;if(glassOnly)logName="glass-checks.txt";if(controlCenterOnly)logName="control-center-checks.txt";contourOnly=Array.IndexOf(args,"--contour-only")>=0;if(contourOnly)logName="contour-checks.txt";if(materialOnly)logName="material-checks.txt";if(editorSyncOnly)logName="editor-sync-checks.txt";root=Path.GetFullPath(args[0]);output=Path.GetFullPath(args[1]);Directory.CreateDirectory(output);Application.EnableVisualStyles();form=new BackgroundWorkspaceTestForm{ClientSize=new Size(1000,720),FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.Manual,Location=new Point(-16000,-16000),ShowInTaskbar=false,Opacity=0};view=new WebView2{Dock=DockStyle.Fill};form.Controls.Add(view);form.Shown+=async(s,e)=>{try{await Run();}catch(Exception ex){File.AppendAllText(Path.Combine(output,logName),ex.ToString());Environment.ExitCode=1;}finally{view.Dispose();form.Close();}};Application.Run(form);}
